<main class="container py-5"><div class="dashboard-head"><div><span class="eyebrow">COACH</span><h1 class="fw-bold">Gestion des activités</h1></div><a href="/coach" class="btn btn-outline-dark">Dashboard</a></div><div class="form-card mb-5"><h3 class="h5 fw-bold">Créer / modifier une activité</h3><form method="post" action="/coach/activites/save" class="row g-3"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" id="activity-id"><div class="col-md-6"><input name="title" id="activity-title" class="form-control" placeholder="Titre" required></div><div class="col-md-3"><select name="category_id" id="activity-category" class="form-select"><?php foreach($categories as $c): ?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach; ?></select></div><div class="col-md-3"><select name="level" id="activity-level" class="form-select"><?php foreach(['Débutant','Intermédiaire','Avancé'] as $l): ?><option><?=$l?></option><?php endforeach; ?></select></div><div class="col-md-6"><input name="short_description" id="activity-short" class="form-control" placeholder="Résumé" required></div><div class="col-md-3"><input type="number" name="duration_minutes" id="activity-duration" class="form-control" placeholder="Durée" required></div><div class="col-md-3"><input type="number" step="0.01" name="price" id="activity-price" class="form-control" placeholder="Prix" required></div><div class="col-md-6"><input name="image_url" id="activity-image" class="form-control" placeholder="URL de l'image"></div><div class="col-md-6"><input name="location" id="activity-location" class="form-control" placeholder="Lieu"></div><div class="col-12"><textarea name="description" id="activity-description" class="form-control" rows="3" placeholder="Description"></textarea></div><div class="col-12"><label class="me-3"><input type="checkbox" name="featured" id="activity-featured" value="1"> À la une</label><label><input type="checkbox" name="active" id="activity-active" value="1" checked> Active</label></div><div><button class="btn btn-accent">Enregistrer</button><button type="button" class="btn btn-light" onclick="location.reload()">Nouveau</button></div></form></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Activité</th><th>Catégorie</th><th>Prix</th><th>État</th><th></th></tr></thead><tbody><?php foreach($activities as $a): ?><tr><td><strong><?=e($a['title'])?></strong><br><small><?=e($a['location'])?></small></td><td><?=e($a['category'])?></td><td><?=$a['price']?> €</td><td><span class="badge text-bg-<?=$a['active']?'success':'secondary'?>"><?=$a['active']?'Active':'Inactive'?></span></td><td class="text-end"><button class="btn btn-sm btn-outline-dark edit-activity" data-json='<?=e(json_encode($a,JSON_UNESCAPED_UNICODE|JSON_HEX_APOS|JSON_HEX_QUOT))?>'>Modifier</button><form class="d-inline" method="post" action="/coach/activites/toggle"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$a['id']?>"><button class="btn btn-sm btn-outline-secondary">Activer/Désactiver</button></form></td></tr><?php endforeach; ?></tbody></table></div></main>